// Verifies web/code-snapshot.json (generated by scripts/gen_code_snapshot.py
// at the repo root from the real python/cpp/rust/csharp source) is present,
// well-formed, and actually covers all four languages for every model
// group -- matches this project's existing *-test.cjs convention.

const fs = require("fs");
const path = require("path");

const SNAPSHOT_PATH = path.join(__dirname, "web", "code-snapshot.json");
const EXPECTED_LANGS = ["python", "cpp", "rust", "csharp"];

function fail(message) {
  console.error(`FAIL: ${message}`);
  process.exitCode = 1;
}

function main() {
  if (!fs.existsSync(SNAPSHOT_PATH)) {
    fail(`${SNAPSHOT_PATH} does not exist -- run: python scripts/gen_code_snapshot.py`);
    return;
  }

  const data = JSON.parse(fs.readFileSync(SNAPSHOT_PATH, "utf8"));
  if (!Array.isArray(data.groups) || data.groups.length === 0) {
    fail("code-snapshot.json has no groups");
    return;
  }

  let checkedSnippets = 0;
  for (const group of data.groups) {
    if (!group.id || !group.title || !group.description) {
      fail(`group missing id/title/description: ${JSON.stringify(group).slice(0, 80)}`);
      continue;
    }
    for (const lang of EXPECTED_LANGS) {
      const entry = group.languages[lang];
      if (!entry) {
        fail(`${group.id}: missing language '${lang}'`);
        continue;
      }
      if (!Array.isArray(entry.paths) || entry.paths.length === 0) {
        fail(`${group.id}/${lang}: no source paths recorded`);
      }
      if (!entry.code || entry.code.trim().length < 20) {
        fail(`${group.id}/${lang}: code snippet is missing or suspiciously short`);
      }
      checkedSnippets++;
    }
  }

  const expectedGroups = 8;
  if (data.groups.length < expectedGroups) {
    fail(`expected at least ${expectedGroups} model groups, found ${data.groups.length}`);
  }

  if (process.exitCode === 1) return;
  console.log(JSON.stringify({
    groups: data.groups.length,
    snippets: checkedSnippets,
    status: "code-snapshot.json is well-formed and covers all four languages for every group",
  }, null, 2));
}

main();
